import React, { useState } from 'react';

function App() {
  const [email, setEmail] = useState('');
  const [error, setError] = useState('');
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [isCreatingPassword, setIsCreatingPassword] = useState(false);
  const [passwordSent, setPasswordSent] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!email.endsWith('@brokenmachines')) {
      setError('Only @brokenmachines emails are allowed');
      return;
    }
    setIsLoggedIn(true);
    setError('');
  };

  const handleCreatePassword = (e) => {
    e.preventDefault();
    if (!email.endsWith('@brokenmachines')) {
      setError('Only @brokenmachines emails are allowed');
      return;
    }
    // Simulate sending email with new password
    setPasswordSent(true);
    setError('');
    // In a real app, you would make an API call here to handle password creation
  };

  if (isLoggedIn) {
    return (
      <div className="min-h-screen bg-gray-100 p-8">
        <div className="max-w-4xl mx-auto bg-white rounded-lg shadow p-6">
          <h1 className="text-2xl font-bold text-center">Welcome!</h1>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gray-100 flex items-center justify-center p-8">
      <div className="max-w-md w-full bg-white rounded-lg shadow-lg p-8">
        <h1 className="text-2xl font-bold text-center mb-8">
          {isCreatingPassword ? 'Create Password' : 'Login'}
        </h1>

        {passwordSent ? (
          <div className="text-center space-y-4">
            <p className="text-green-600">
              Password creation instructions have been sent to your email!
            </p>
            <button
              onClick={() => {
                setIsCreatingPassword(false);
                setPasswordSent(false);
              }}
              className="text-blue-600 hover:text-blue-800 underline"
            >
              Return to login
            </button>
          </div>
        ) : (
          <form onSubmit={isCreatingPassword ? handleCreatePassword : handleSubmit} className="space-y-6">
            <div>
              <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-2">
                Email
              </label>
              <input
                type="email"
                id="email"
                value={email}
                onChange={(e) => setEmail(e.target.value)}
                className="w-full px-4 py-2 border border-gray-300 rounded-md focus:ring-2 focus:ring-blue-500 focus:border-blue-500"
                placeholder="your-email@brokenmachines"
                required
              />
              {error && (
                <p className="mt-2 text-sm text-red-600">
                  {error}
                </p>
              )}
            </div>

            <button
              type="submit"
              className="w-full bg-blue-600 text-white py-2 px-4 rounded-md hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 transition-colors"
            >
              {isCreatingPassword ? 'Send Password Instructions' : 'Sign In'}
            </button>

            <div className="text-center">
              <button
                type="button"
                onClick={() => setIsCreatingPassword(!isCreatingPassword)}
                className="text-blue-600 hover:text-blue-800 text-sm"
              >
                {isCreatingPassword ? 'Back to login' : 'Create new password'}
              </button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

export default App;
